import fs from 'node:fs';

function read(path) {
  return fs.readFileSync(path, 'utf8');
}

function write(path, content) {
  fs.writeFileSync(path, content);
}

function replaceOnce(path, before, after) {
  const source = read(path);
  const first = source.indexOf(before);
  if (first < 0) throw new Error(`Missing patch anchor in ${path}: ${before.slice(0, 100)}`);
  if (source.indexOf(before, first + before.length) >= 0) {
    throw new Error(`Non-unique patch anchor in ${path}: ${before.slice(0, 100)}`);
  }
  write(path, source.slice(0, first) + after + source.slice(first + before.length));
}

function replaceBetween(path, start, end, replacement) {
  const source = read(path);
  const startIndex = source.indexOf(start);
  if (startIndex < 0) throw new Error(`Missing start anchor in ${path}: ${start}`);
  const endIndex = source.indexOf(end, startIndex + start.length);
  if (endIndex < 0) throw new Error(`Missing end anchor in ${path}: ${end}`);
  write(path, source.slice(0, startIndex) + replacement + source.slice(endIndex));
}

